body.script:
(() => {
const token = location.pathname.split('/').pop();
const csrf = document.body.dataset.csrf;
const $ = id => document.getElementById(id);
let current = null;
let pending = null;
async function call(operation, args = {}) {
 const response = await fetch('/jobhunter/interview/rpc', {method:'POST', credentials:'same-origin', headers:{'Content-Type':'application/json'}, body:JSON.stringify({jsonrpc:'2.0',id:Date.now(),method:'call',params:{token,operation,arguments:args,csrf_token:csrf}})});
 const payload = await response.json();
 if (!response.ok || payload.error || payload.result?.error) throw new Error(payload.result?.error?.message || 'Interview unavailable. Refresh to resume.');
 return payload.result;
}
function render(session) {
 current = session.current_question;
 $('progress').textContent = `${session.submitted_count} of ${session.question_count} answers submitted · ${session.status}`;
 $('response').hidden = !session.response_required;
 $('question').hidden = !current;
 $('finish').hidden = !['awaiting_answers','in_progress'].includes(session.status);
 $('question-text').textContent = current?.question || '';
 $('follow-up').textContent = current?.follow_up || '';
 $('answer').value = '';
 $('answers').replaceChildren();
 for (const answer of session.answers) { const heading = document.createElement('h3');heading.textContent=answer.question;const text=document.createElement('pre');text.textContent=answer.answer;$('answers').append(heading,text); }
}
async function action(fn) { $('error').textContent='';for(const id of ['submit','finish','accept','decline'])$(id).disabled=true;try {await fn();}catch(error){$('error').textContent=error.message;}finally{for(const id of ['submit','finish','accept','decline'])$(id).disabled=false;} }
$('accept').onclick = () => action(async()=>render((await call('respond',{response:'accepted'})).session));
$('decline').onclick = () => action(async()=>render((await call('respond',{response:'declined'})).session));
$('submit').onclick = () => action(async()=>{const text=$('answer').value;if(!text.trim())throw new Error('Enter an answer before submitting.');if(!pending || pending.text!==text || pending.question_id!==current.id)pending={question_id:current.id,client_answer_id:crypto.randomUUID(),text};const result=await call('answer',pending);pending=null;render(result.session);});
$('finish').onclick = () => action(async()=>{render((await call('finish')).session);});
action(async()=>render((await call('get')).session));
})();
